function summary = runFrameGridImpactValidation(options)
%RUNFRAMEGRIDIMPACTVALIDATION Execute the 12-work-item impact contract.
%
% The campaign compares rows generated by the canonical production
% frame/grid resolvers.  TruthQualified remains false because these
% deterministic component comparisons are not waveform-link truth.

arguments
    options.VectorRoot (1,1) string
    options.BaseArtifactDir (1,1) string
    options.OutputDir (1,1) string
    options.Strict (1,1) logical = true
    options.StudyConfig (1,1) string = ""
end

if ~options.Strict
    error("sixgr:frame:StrictValidationRequired", ...
        "Frame-grid impact execution requires Strict=true.");
end
repoRoot = localRepositoryRoot();
if strlength(options.StudyConfig) == 0
    options.StudyConfig = fullfile(repoRoot, "simulator", "configs", ...
        "validation", "frame_grid_impact.yaml");
end
cfg = sixgr.lls6g.config.readConfigFile(options.StudyConfig);
localValidateConfig(cfg);

matrixPath = fullfile(options.VectorRoot, ...
    "frame_impact_experiment_matrix.csv");
rulesPath = fullfile(options.VectorRoot, ...
    "frame_impact_acceptance_rules.csv");
csvContractPath = fullfile(options.VectorRoot, ...
    "desired_frame_impact_csv_contract.csv");
imageContractPath = fullfile(options.VectorRoot, ...
    "desired_frame_impact_image_contract.csv");
for path = [matrixPath, rulesPath, csvContractPath, imageContractPath]
    if ~isfile(path)
        error("sixgr:frame:ImpactInputMissing", ...
            "Required frame-grid impact input is missing: %s.", path);
    end
end

% Fail fast against the canonical production APIs as well as the persisted
% artifact contract.
numerology = sixgr.phy.frame.NumerologyCatalog.resolve( ...
    30, "normal", "generic_waveform_test", "FR1");
if numerology.SlotsPerFrame ~= 20
    error("sixgr:frame:ImpactProductionProbeFailed", ...
        "The canonical numerology probe returned an invalid timeline.");
end
carrier = sixgr.phy.frame.CarrierGridConfig.resolve( ...
    "Role", "gNB_carrier_transmission_bandwidth", ...
    "FrequencyRange", "FR1", "CenterFrequencyHz", 4.0e9, ...
    "ChannelBandwidthMHz", 10, "SubcarrierSpacingKHz", 15);
if carrier.NSizeGrid <= 0
    error("sixgr:frame:ImpactProductionProbeFailed", ...
        "The canonical carrier-grid probe returned no resource blocks.");
end

baseVerifier = fullfile(options.VectorRoot, "verify_frame_artifacts.py");
command = sprintf('python "%s" "%s"', baseVerifier, ...
    options.BaseArtifactDir);
[baseVerifierExit, verifierOutput] = system(command);
if baseVerifierExit ~= 0
    error("sixgr:frame:BaseArtifactVerificationFailed", ...
        "Base frame-grid artifacts failed verification (exit %d): %s", ...
        baseVerifierExit, verifierOutput);
end

csvContract = localReadStrings(csvContractPath);
imageContract = localReadStrings(imageContractPath);
outputDir = string(java.io.File(char(options.OutputDir)).getCanonicalPath());
if ~isfolder(outputDir)
    [ok, message] = mkdir(outputDir);
    if ~ok
        error("sixgr:frame:ImpactArtifactWriteFailed", ...
            "Unable to create %s: %s.", outputDir, message);
    end
end
localCleanContracted(outputDir, csvContract, imageContract);

runID = "frame_grid_impact_" + string(datetime("now", ...
    TimeZone="UTC", Format="yyyyMMdd'T'HHmmss'Z'"));
[tables, evidence] = ...
    sixgr.phy.frame.analysis.FrameGridImpactEvidenceBuilder.build( ...
        matrixPath, rulesPath, options.VectorRoot, ...
        options.BaseArtifactDir, cfg, runID, baseVerifierExit);

names = string(fieldnames(tables));
rowCounts = struct();
csvHashes = struct();
for index = 1:numel(names)
    fileName = names(index) + ".csv";
    sixgr.phy.frame.analysis.FrameGridImpactArtifactExporter. ...
        writeTable(outputDir, fileName, tables.(names(index)));
    rowCounts.(names(index)) = height(tables.(names(index)));
    csvHashes.(names(index)) = ...
        sixgr.phy.frame.analysis.FrameGridImpactArtifactExporter. ...
        fileHash(fullfile(outputDir, fileName));
end

auditRows = repmat(localAuditRow(), height(imageContract), 1);
for index = 1:height(imageContract)
    auditRows(index) = ...
        sixgr.phy.frame.analysis.FrameGridImpactArtifactExporter. ...
        writeSemanticFigure(outputDir, ...
            table2struct(imageContract(index, :)), cfg);
end
audit = struct2table(auditRows, AsArray=true);
sixgr.phy.frame.analysis.FrameGridImpactArtifactExporter.writeTable( ...
    outputDir, "frame_impact_image_semantic_audit.csv", audit);
rowCounts.frame_impact_image_semantic_audit = height(audit);
csvHashes.frame_impact_image_semantic_audit = ...
    sixgr.phy.frame.analysis.FrameGridImpactArtifactExporter.fileHash( ...
        fullfile(outputDir, "frame_impact_image_semantic_audit.csv"));

expectedCSV = string(csvContract.FileName);
expectedPNG = string(imageContract.ImageFile);
csvPresent = arrayfun(@(name) isfile(fullfile(outputDir, name)), ...
    expectedCSV);
pngPresent = arrayfun(@(name) isfile(fullfile(outputDir, name)), ...
    expectedPNG);
passed = all(csvPresent) && all(pngPresent) && ...
    evidence.ExperimentCount == double(cfg.execution.required_experiments) && ...
    evidence.FamilyCount == double(cfg.execution.required_families) && ...
    evidence.RuleCount == double(cfg.execution.required_rules) && ...
    evidence.CompletedCount == evidence.ExperimentCount && ...
    evidence.IncompleteCount == 0 && evidence.HardRulesPassed;

summary = struct( ...
    "Passed", logical(passed), "Status", localStatus(passed), ...
    "Strict", true, "RunID", runID, "OutputDir", outputDir, ...
    "StudyConfig", options.StudyConfig, ...
    "BaseArtifactDir", options.BaseArtifactDir, ...
    "BaseArtifactVerifierExit", baseVerifierExit, ...
    "ExperimentCount", evidence.ExperimentCount, ...
    "CompletedCount", evidence.CompletedCount, ...
    "FamilyCount", evidence.FamilyCount, ...
    "PairCount", evidence.PairCount, ...
    "RuleCount", evidence.RuleCount, ...
    "HardRuleCount", evidence.HardRuleCount, ...
    "HardRulePassCount", evidence.HardRulePassCount, ...
    "IncompleteCount", evidence.IncompleteCount, ...
    "CSVCount", sum(csvPresent), "PNGCount", sum(pngPresent), ...
    "RowCounts", rowCounts, "CSVHashes", csvHashes, ...
    "ExecutionBackend", evidence.ExecutionBackend, ...
    "ApproximationMode", evidence.ApproximationMode, ...
    "TruthQualified", false);
if ~summary.Passed
    error("sixgr:frame:IncompleteImpactCampaign", ...
        "Frame-grid impact campaign did not satisfy its contract.");
end
end

function localValidateConfig(cfg)
required = [ ...
    "evidence.execution_backend","evidence.approximation_mode", ...
    "evidence.truth_qualified","execution.required_experiments", ...
    "execution.required_families","execution.required_rules", ...
    "images.width_pixels","images.height_pixels", ...
    "images.resolution_dpi"];
for path = required
    if isempty(sixgr.util.structGet(cfg, path, []))
        error("sixgr:frame:ImpactStudyConfigInvalid", ...
            "StudyConfig requires field %s.", path);
    end
end
if logical(cfg.evidence.truth_qualified)
    error("sixgr:frame:ImpactTruthRelabelForbidden", ...
        "Comparative component evidence cannot claim waveform truth.");
end
end

function localCleanContracted(outputDir, csvContract, imageContract)
for target = [string(csvContract.FileName); ...
        string(imageContract.ImageFile)].'
    path = fullfile(outputDir, target);
    if isfile(path)
        delete(path);
    end
end
end

function value = localReadStrings(path)
options = detectImportOptions(path, FileType="text", Delimiter=",", ...
    VariableNamingRule="preserve");
options = setvartype(options, options.VariableNames, "string");
value = readtable(path, options);
end

function row = localAuditRow()
row = struct( ...
    "ImageFile", "", "SourceCSV", "", "Width", NaN, "Height", NaN, ...
    "AxesCount", NaN, "SeriesCount", NaN, "FinitePointCount", NaN, ...
    "ExpectedXLabel", "", "ActualXLabel", "", ...
    "ExpectedYLabel", "", "ActualYLabel", "", ...
    "ExpectedTitleToken", "", "ActualTitle", "", ...
    "SourceCSV_SHA256", "", "PNG_SHA256", "", "Status", "");
end

function value = localStatus(tf)
if tf
    value = "PASS";
else
    value = "FAIL";
end
end

function root = localRepositoryRoot()
root = fileparts(mfilename("fullpath"));
for index = 1:4
    root = fileparts(root);
end
end
